<template>
  <v-container class="site-page site-page--readable site-stack">
    <SitePageHeader :summary="experienceSummary" :title="titles.experiencePage"/>
    <ExperienceTimeline :experiences="model.profile.experience"/>
  </v-container>
</template>

<script lang="ts">
import {Component} from 'vue-property-decorator'
import PortalPageBase from '@/view/PortalPageBase'
import {breadcrumbList, canonicalUrl, pageMetaInfo, personReference, socialCardPath, stripHtml} from '@/model/Seo'
import {brandName} from '@/model/Brand'
import ExperienceTimeline from '@/view/Experience/ExperienceTimeline.vue'
import SitePageHeader from '@/view/SitePageHeader.vue'

@Component({components: {ExperienceTimeline, SitePageHeader}})
export default class Experience extends PortalPageBase {
  pageTitle = this.titles.experiencePage

  get experienceSummary() {
    return `${this.model.profile.name} · ${this.model.profile.title} · ${this.model.profile.fullCareerDates}`
  }

  metaInfo(): any {
    const structuredData = {
      '@context': 'https://schema.org',
      '@graph': [
        {
          '@type': 'ProfilePage',
          name: this.titles.experiencePage,
          description: this.titles.experienceDescription,
          url: canonicalUrl(this.constants.experiencePath),
          mainEntity: {
            ...personReference(),
            '@type': 'Person',
            name: stripHtml(this.model.profile.name),
            jobTitle: stripHtml(this.model.profile.title)
          }
        },
        breadcrumbList([
          {name: brandName, path: '/'},
          {name: this.titles.homePage, path: this.constants.introductionPath},
          {name: this.titles.experiencePage, path: this.constants.experiencePath}
        ])
      ]
    }
    return pageMetaInfo(
      this.titles.experienceSeoTitle,
      this.titles.experienceDescription,
      this.constants.experiencePath,
      socialCardPath(this.constants.experiencePath),
      structuredData
    )
  }

  beforeRouteEnter(to: any, from: any, next: any) {
    super.beforeRouteEnter(to, from, next)
  }
}
</script>
